  {"contract":"js/cuw/models/cuw_model.js::CuwModel.prototype.switchToWholeRepro@25100","member":"js/cuw/models/cuw_model.js","span":[25100,25179],"semantics":"Stores caller boolean/value in isWholeReproSwitched; no backend call.","id":"js/cuw/models/cuw_model.js::CuwModel.prototype.switchToWholeRepro@25100","owner":"FlashingFrontend","source_ids":["cuw_utility.cuw-model"]},
  {"contract":"js/cuw/models/cuw_model.js::CuwModel.prototype.clearStatusOfReprogramming@25590","member":"js/cuw/models/cuw_model.js","span":[25590,25711],"semantics":"Forwards isForced; actual cleanup remains backend-owned.","id":"js/cuw/models/cuw_model.js::CuwModel.prototype.clearStatusOfReprogramming@25590","owner":"FlashingFrontend","source_ids":["cuw_utility.cuw-model"]},
  {"contract":"js/cuw/models/cuw_model.js::CuwModel.prototype.disconnect@25986","member":"js/cuw/models/cuw_model.js","span":[25986,26064],"semantics":"Sends CUW Disconnect command; this method does not close the WebSocket.","id":"js/cuw/models/cuw_model.js::CuwModel.prototype.disconnect@25986","owner":"FlashingFrontend","source_ids":["cuw_utility.cuw-model"]},
